gEZ(){return"\u0648\u0635\u064a \u0642\u0627\u0646\u0648\u0646\u064a (\u0648\u062d\u0627\u0645\u064d \u062f\u0627\u0626\u0645\u064b\u0627)"},
gFn(){return"\u0628\u0644\u063a \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649 (5)"},
gF8(){return"\u0628\u0644\u063a \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649 (2)"},
gF6(){return"\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u062f\u0639\u0648\u0629"},
gFg(){return"\u0627\u0644\u062f\u0639\u0648\u0629 \u062c\u0627\u0647\u0632\u0629"},
