FG(a){return"\u0623\u064f\u0631\u0633\u0644\u062a \u0627\u0644\u062f\u0639\u0648\u0629 \u0645\u0646 "+a+" \u0634\u062e\u0635\u064a\u064b\u0627."},
gFJ(){return"\u062a\u0633\u0627\u0639\u062f Lyhanna \u0639\u0644\u0649 \u0625\u064a\u062c\u0627\u062f \u0627\u0644\u0645\u0641\u0642\u0648\u062f \u0628\u0633\u0631\u0639\u0629. \u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0644\u0645\u0648\u062b\u0648\u0642\u0648\u0646 \u0647\u0645 \u0645\u0646 \u0642\u062f \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u0641\u0642\u0648\u062f \u0639\u0646\u062f\u0647\u0645\u060c \u0623\u0648 \u0642\u062f \u062a\u0643\u0648\u0646 \u0644\u062f\u064a\u0647\u0645 \u0623\u062e\u0628\u0627\u0631\u0647."},
gFz(){return"\u0644\u0643 \u0627\u0644\u062d\u0631\u064a\u0629 \u0641\u064a \u0627\u0644\u0642\u0628\u0648\u0644 \u0623\u0648 \u0627\u0644\u0631\u0641\u0636\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0627\u0631 \u064a\u062e\u0635\u0651\u0643 \u0648\u062d\u062f\u0643."},
vq(a){return"\u0625\u0630\u0627 \u0642\u0628\u0644\u062a\u060c \u0641\u0633\u062a\u064f\u062d\u0641\u0638 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0644\u0633\u0628\u0628 \u0648\u0627\u062d\u062f \u0641\u0642\u0637: \u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0643 \u0625\u0646 \u0644\u0632\u0645 \u064a\u0648\u0645\u064b\u0627 \u0627\u0644\u0628\u062d\u062b \u0639\u0646 "+a+". \u0648\u0644\u0646 \u062a\u0643\u0648\u0646 \u0645\u0631\u0626\u064a\u0629 \u0625\u0644\u0627 \u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0644\u062b\u0642\u0629 \u0627\u0644\u062e\u0627\u0635\u064a\u0646 \u0628\u0640"+a+" \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0644\u0644\u062a\u0646\u0633\u064a\u0642 \u0628\u064a\u0646 \u0627\u0644\u0645\u0642\u0631\u0628\u064a\u0646 \u2014 \u0644\u0627 \u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0622\u062e\u0631\u064a\u0646\u060c \u0648\u0644\u0627 \u062a\u064f\u0646\u0634\u0631 \u0623\u0628\u062f\u064b\u0627. \u0644\u0627 \u0625\u0639\u0644\u0627\u0646\u0627\u062a\u060c \u0648\u0644\u0627 \u062a\u062a\u0628\u0639 \u0644\u0645\u0648\u0642\u0639\u0643."},
gFO(){return"\u064a\u0645\u0643\u0646\u0643 \u0637\u0644\u0628 \u062d\u0630\u0641\u0647\u0627 \u0641\u064a \u0623\u064a \u0648\u0642\u062a."},
