gF1(){return"\u062a\u0645 \u0627\u0644\u0646\u0633\u062e."},
gFj(){return"\u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u063a\u064a\u0631 \u0645\u0631\u062a\u0628\u0637 \u2014 \u0644\u0646 \u064a\u062a\u0644\u0642\u0649 \u0647\u0630\u0627 \u0627\u0644\u0634\u062e\u0635 \u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0646\u0628\u064a\u0647."},
gFx(){return"\u064a\u0645\u0643\u0646\u0643 \u0644\u0635\u0642 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0643\u0627\u0645\u0644\u0629: \u0633\u064a\u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u0631\u0645\u0632."},
gF7(){return"\u0623\u0646\u062a \u0631\u0627\u0634\u062f: \u0644\u0627 \u062a\u062d\u062f\u0651\u062f \u0647\u0630\u0627 \u0627\u0644\u062e\u064a\u0627\u0631 \u0625\u0644\u0627 \u0625\u0630\u0627 \u0643\u0646\u062a \u062a\u062d\u062a \u0627\u0644\u0648\u0635\u0627\u064a\u0629 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629."},
gFK(){return"\u062d\u0630\u0641"},
gFM(){return"\u062a\u0645\u0651. \u062a\u0645 \u0645\u062d\u0648 \u0628\u064a\u0627\u0646\u0627\u062a\u0643."},
