gK4(){return"\u062d\u0641\u0638 \u0628\u064a\u0627\u0646\u0627\u062a\u064a"},
gK5(){return"\u062a\u0645 \u062d\u0641\u0638 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a."},
gEQ(){return"\u0627\u062e\u062a\u0631 \u0645\u0646 \u062a\u0637\u0644\u0628 \u0645\u0646\u0647. \u0633\u064a\u0631\u0649 \u0647\u0624\u0644\u0627\u0621 \u0623\u064a\u0646 \u0623\u0646\u062a."},
gEX(){return"\u0623\u064a\u0646 \u0623\u0646\u062a\u061f (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gET(){return"\u0627\u062e\u062a\u0631 \u0634\u062e\u0635\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644"},
EO(a){return"\u0627\u0644\u0637\u0644\u0628 \u0645\u0646 "+a+" \u0634\u062e\u0635"},
gEV(){return"\u062a\u0645 \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0637\u0644\u0628."},
gEW(){return"\u062a\u0645 \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0637\u0644\u0628 \u2014 \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u0631\u062f."},
ES(a,b){return a+" \u0641\u064a \u0627\u0644\u0637\u0631\u064a\u0642 (\u0645\u0646\u0630 "+b+")."},
